use crate::{db::Database,error::{ObError,ObResult},models::ToolDefinition};
use rusqlite::params;
#[derive(Clone)]pub struct ToolRegistry{definitions:Vec<ToolDefinition>}
impl ToolRegistry{pub fn load(db:&Database)->ObResult<Self>{let definitions:Vec<ToolDefinition>=serde_json::from_str(include_str!("../../../tools/registry.json"))?;let now=chrono::Utc::now().to_rfc3339();for tool in &definitions{db.execute(|connection|{connection.execute("INSERT INTO tools(name,definition_json,enabled,updated_at) VALUES(?1,?2,?3,?4) ON CONFLICT(name) DO UPDATE SET definition_json=excluded.definition_json,updated_at=excluded.updated_at",params![tool.name,serde_json::to_string(tool)?,tool.enabled_by_default as i32,now])?;Ok(())})?}Ok(Self{definitions})}pub fn get(&self,name:&str)->ObResult<&ToolDefinition>{self.definitions.iter().find(|tool|tool.name==name).ok_or_else(||ObError::Validation(format!("Tool is not registered: {name}")))}pub fn all(&self)->&[ToolDefinition]{&self.definitions}}
